request.query:
query GetSkills {
  skills {
    name
    description
    content
    rootPath
    fileCount
    isReadonly
    isDisabled
    __typename
  }
}

query GetMcpServers {
  mcpServers {
    __typename
    ... on StdioMcpServerConfig {
      serverId
      transportType
      enabled
      toolNamePrefix
      command
      args
      env
      cwd
      __typename
    }
    ... on StreamableHttpMcpServerConfig {
      serverId
      transportType
      enabled
      toolNamePrefix
      url
      token
      headers
      __typename
    }
  }
}

query GetDefinitionProblems($kind: DefinitionKind!) {
  definitionProblems(kind: $kind) {
    kind
    definitionId
    code
    reason
    definitionPath
    packageRoot
    usingLastGood
    dependencyChain
    __typename
  }
}

query ListCollaborationRootHistory {
  listCollaborationRootHistory {
    __typename
    ... on AgentOrgRootHistoryObject {
      root_subject_kind
      root_run_id
      created_at
      archived_at
      is_active
      summary
      org
      closed_task_executions
      __typename
    }
    ... on AgentTeamRootHistoryObject {
      root_subject_kind
      root_run_id
      __typename
    }
  }
}
